<template><Head><title>Выпуск №{{ run.id }}</title></Head><div class="mi-page"><div class="content-header"><div class="container-fluid"><h5 class="m-0">Выпуск производства №{{ run.id }}</h5></div></div><div class="content"><div class="container-fluid"><div class="card"><div class="card-body"><dl class="row mi-summary"><dt class="col-sm-3">Продукция</dt><dd class="col-sm-9">{{ run.nomenclature }}</dd><dt class="col-sm-3">Количество</dt><dd class="col-sm-9">{{ run.quantity }} {{ run.unit }}</dd><dt class="col-sm-3">Дата</dt><dd class="col-sm-9">{{ run.produced_at }}</dd><dt class="col-sm-3">Рецепт</dt><dd class="col-sm-9">v{{ run.recipe_version }}</dd><dt class="col-sm-3">Статус</dt><dd class="col-sm-9">{{ labels[run.status] }}</dd></dl><h6>Расход по рецепту</h6><div class="table-responsive mi-table-wrap"><table class="table table-bordered mi-mobile-table"><thead><tr><th>Материал</th><th>На единицу</th><th>Всего</th></tr></thead><tbody><tr v-for="item in recipe_items"><td data-label="Материал">{{ item.material }}</td><td data-label="На единицу">{{ item.quantity_per_unit }} {{ item.unit }}</td><td data-label="Всего">{{ item.quantity }} {{ item.unit }}</td></tr></tbody></table></div><template v-if="consumption.length"><h6>Созданные движения</h6><div class="table-responsive mi-table-wrap"><table class="table table-bordered mi-mobile-table"><tbody><tr v-for="item in consumption"><td data-label="Материал">{{ item.material }}</td><td data-label="Количество">{{ item.quantity }} {{ item.unit }}</td></tr></tbody></table></div></template></div><div class="card-footer mi-actions"><Link v-if="run.status === 'draft'" :href="route('production-runs.edit', run.id)" class="btn btn-outline-primary">Изменить</Link><button v-if="run.status === 'draft'" class="btn btn-success" @click="complete">Провести</button><button v-if="run.status === 'completed'" class="btn btn-danger" @click="cancel">Отменить производство</button><Link :href="route('production-runs.index')" class="btn btn-default">К списку</Link></div></div></div></div></div></template>
<script>import {Head, Link} from '@inertiajs/inertia-vue3'; export default {components: {Head, Link}, props: ['run', 'recipe_items', 'consumption', 'statusLabels'], computed: {labels() { return this.statusLabels || {} }}, methods: {complete() { if (confirm('Провести выпуск и списать материалы?')) this.$inertia.post(route('production-runs.complete', this.run.id)) }, cancel() { if (confirm('Отменить выпуск и вернуть материалы?')) this.$inertia.post(route('production-runs.cancel', this.run.id)) }}};</script>
